# Builds man/figures/logo.png, the hex sticker used by pkgdown and README.md.
# Run from the package root: Rscript pkgdown/logo/make_logo.R
#
# ernie-hourglass.png was generated by the local ERNIE-Image-Turbo model
# (Apache-2.0); its prompt and seed are in ernie-hourglass.json. hourglass.png
# is that image cropped, with the navy background keyed out to transparency.
# The palette follows the pixel-art hourglass of Mistral AI's Timestral
# announcement.

library(hexSticker)

navy <- "#0B183D"
orange <- "#FA500F"

sysfonts::font_add_google("Pixelify Sans", "pixelify")
showtext::showtext_auto()

sticker(
  "pkgdown/logo/hourglass.png",
  s_x = 1, s_y = 1.12, s_width = 0.29,
  package = "timestralR",
  p_family = "pixelify", p_size = 21, p_y = 0.5, p_color = "white",
  h_fill = navy, h_color = orange, h_size = 1.6,
  url = "sjvrensburg.github.io/timestralR", u_size = 4,
  u_color = "#7FC4F5", u_family = "pixelify",
  filename = "man/figures/logo.png", dpi = 600
)
